mapper.select:
WITH SELECT FROM scm01_sr INNER JOIN emp01_person ON emp01_person_id = scm01_person_id LEFT OUTER JOIN sys15_corp ON sys15_corp_id = scm01_corp_id LEFT OUTER JOIN LATERAL ( SELECT COUNT(*) dev_total_cnt , SUM(CASE WHEN f_get_dev_status(scm10_dev_id) = '완료' THEN 1 ELSE 0 END) dev_end_cnt FROM scm10_dev WHERE scm10_sr_id = scm01_sr_id ) t ON TRUE LEFT JOIN systemCode ON systemCode.cd = scm01_system_cd LEFT JOIN srType ON srType.cd = scm01_sr_type LEFT JOIN aprStatusCode ON aprStatusCode.cd = scm01_appr_status_cd LEFT JOIN srStatus ON srStatus.cd = scm01_sr_status_cd LEFT JOIN devImportanceCode ON devImportanceCode.cd = scm01_dev_importance_cd WHERE scm01_sr_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date) AND COALESCE(scm01_system_cd, '%') LIKE #{systemCode} AND COALESCE(scm01_sr_status_cd, '10') LIKE #{srStatus}
AND CONCAT( emp01_kor_nm , sys15_corp_nm , scm01_requestor , scm01_sr_content , scm01_result_content , ( SELECT ARRAY_TO_STRING(ARRAY_AGG(f_emp_kor_nm(scm02_step_emp_id)), '') FROM scm02_sr_appr_step WHERE scm02_sr_id = scm01_sr_id ) , scm01_sr_no ) ILIKE #{searchText}
AND COALESCE(scm01_sr_status_cd,'10') NOT IN ('30','90')
AND COALESCE(scm01_appr_status_cd,'99') NOT IN ('30','40')
AND scm01_person_id = #{personId}
ORDER BY scm01_sr_date DESC, scm01_sr_id DESC

mapper.update:
UPDATE scm01_sr
   SET scm01_sr_content = #{srContent}
 WHERE scm01_sr_id = #{srId}

UPDATE scm01_sr
   SET scm01_appr_status_cd = #{apprStatusCd}
 WHERE scm01_sr_id = #{srId}

UPDATE scm01_sr
   SET scm01_result_content = #{resultContent}
 WHERE scm01_sr_id = #{srId}

mapper.delete:
DELETE FROM scm01_sr
 WHERE scm01_sr_id IN
#{srId}
